let QURAN_DATA, state, meta, currentSurah = null, quizMode = "next", currentAudio = null, showMeaning = true;

const AudioFX = {
  ctx: null,
  enabled: true,
  init(){
    if(!this.ctx){
      try{ this.ctx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){}
    }
    if(this.ctx && this.ctx.state === 'suspended'){
      try{ this.ctx.resume(); }catch(e){}
    }
  },
  _beep(freq, dur, type, vol, slideTo){
    if(!this.enabled) return;
    try{
      this.init();
      if(!this.ctx) return;
      const t = this.ctx.currentTime;
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = type || 'sine';
      o.frequency.setValueAtTime(freq, t);
      if(slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(40, slideTo), t + dur);
      g.gain.setValueAtTime(Math.max(0.001, vol || 0.12), t);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      o.connect(g); g.connect(this.ctx.destination);
      o.start(t); o.stop(t + dur + 0.02);
    }catch(e){}
  },
  playCorrect(){
    if(!this.enabled) return;
    this._beep(523, 0.12, 'sine', 0.14, 780);
    setTimeout(()=>{ this._beep(880, 0.16, 'sine', 0.12); }, 90);
  },
  playWrong(){
    if(!this.enabled) return;
    this._beep(180, 0.18, 'sawtooth', 0.1, 90);
  },
  playClick(){
    if(!this.enabled) return;
    this._beep(420, 0.05, 'triangle', 0.07);
  },
  playTap(){ this.playClick(); },
  playFlip(){
    if(!this.enabled) return;
    this._beep(320, 0.08, 'triangle', 0.08, 520);
  },
  playMatch(){
    if(!this.enabled) return;
    this._beep(600, 0.1, 'sine', 0.12, 900);
    setTimeout(()=>{ this._beep(1000, 0.14, 'sine', 0.1); }, 80);
  },
  playCoin(){
    if(!this.enabled) return;
    this._beep(980, 0.07, 'square', 0.05);
    setTimeout(()=>{ this._beep(1320, 0.1, 'square', 0.04); }, 60);
  },
  playWhoosh(){
    if(!this.enabled) return;
    this._beep(240, 0.12, 'triangle', 0.06, 120);
  },
  playNav(){
    if(!this.enabled) return;
    this._beep(520, 0.07, 'sine', 0.12, 720);
    setTimeout(()=>{ this._beep(780, 0.08, 'sine', 0.09); }, 55);
  },
  playSuccess(){
    if(!this.enabled) return;
    this._beep(523, 0.1, 'sine', 0.12);
    setTimeout(()=>{ this._beep(659, 0.1, 'sine', 0.12); }, 100);
    setTimeout(()=>{ this._beep(784, 0.18, 'sine', 0.12); }, 200);
  },
  playLock(){
    if(!this.enabled) return;
    this._beep(140, 0.15, 'square', 0.06);
  },
  playPop(){
    if(!this.enabled) return;
    this._beep(700, 0.06, 'triangle', 0.08, 1100);
  },
  playSoft(){
    if(!this.enabled) return;
    this._beep(360, 0.07, 'sine', 0.05);
  },
  playStart(){
    if(!this.enabled) return;
    this._beep(440, 0.08, 'sine', 0.1, 660);
    setTimeout(()=>{ this._beep(880, 0.12, 'sine', 0.09); }, 100);
  },
  playTick(){
    if(!this.enabled) return;
    this._beep(900, 0.03, 'square', 0.035);
  },
  playToggle(){
    if(!this.enabled) return;
    this._beep(480, 0.05, 'triangle', 0.07, 620);
  },
  playBismillah(){
    // Real qira'at — opening splash ONLY (once)
    if(window.__bismillahPlayed || window.__bismillahPlaying) return;
    try{
      this.stopBismillah();
      var a = document.getElementById('bismillahAudioTag');
      if(!a){
        a = new Audio('audio/bismillah.mp3');
      }
      try{ a.currentTime = 0; }catch(e){}
      a.volume = 1.0;
      a.muted = false;
      this._bismillahAudio = a;
      window.__bismillahPlaying = true;
      var p = a.play();
      if(p && p.then){
        p.then(function(){ window.__bismillahPlayed = true; })
         .catch(function(){
           window.__bismillahPlaying = false;
           try{
             var b = new Audio('audio/bismillah.mp3');
             b.volume = 1;
             AudioFX._bismillahAudio = b;
             b.play().then(function(){ window.__bismillahPlayed = true; }).catch(function(){});
           }catch(e2){}
         });
      }
      a.onended = function(){ window.__bismillahPlaying = false; };
    }catch(e){ window.__bismillahPlaying = false; }
  },
  stopBismillah(){
    try{
      if(this._bismillahAudio){
        this._bismillahAudio.pause();
        try{ this._bismillahAudio.currentTime = 0; }catch(e){}
        this._bismillahAudio = null;
      }
      window.__bismillahPlaying = false;
    }catch(e){}
  }
};



function loadAll(){
  try { QURAN_DATA = JSON.parse(localStorage.getItem(STORAGE_DATA)) || structuredClone(DEFAULT_QURAN); }
  catch(e){ QURAN_DATA = structuredClone(DEFAULT_QURAN); }
  // Always sync Arabic text + ayah count from embedded defaults (fixes old/wrong cache)
  try {
    const src = (typeof currentScript !== 'undefined' && currentScript === 'uthmani')
      ? DEFAULT_QURAN_UTHMANI : DEFAULT_QURAN_INDOPAK;
    Object.keys(src).forEach(function(id){
      const def = src[id];
      if(!def || !def.ayat) return;
      if(!QURAN_DATA[id]) {
        QURAN_DATA[id] = structuredClone(def);
      } else {
        // preserve progress length; refresh text
        QURAN_DATA[id].nameAr = def.nameAr || QURAN_DATA[id].nameAr;
        QURAN_DATA[id].nameTa = def.nameTa || QURAN_DATA[id].nameTa;
        QURAN_DATA[id].surahNum = def.surahNum;
        QURAN_DATA[id].ayat = def.ayat.map(function(a){ return { ar: a.ar }; });
      }
    });
  } catch(e){}
  try {
    state = JSON.parse(localStorage.getItem(STORAGE_GAME)) || {coins:0, gardens:{}};
  } catch(e){ state = {coins:0, gardens:{}}; }
  Object.keys(QURAN_DATA).forEach(id=>{
    const need = QURAN_DATA[id].ayat.length;
    if(!state.gardens[id]) state.gardens[id] = {planted: Array(need).fill(false)};
    else if(state.gardens[id].planted.length !== need){
      const old = state.gardens[id].planted;
      state.gardens[id].planted = Array.from({length:need}, (_,i)=>!!old[i]);
    }
  });
  try { meta = JSON.parse(localStorage.getItem(STORAGE_META)) || {streak:0,lastPlay:null,dailyCount:0,dailyDate:null,badges:{},sound:true}; }
  catch(e){ meta = {streak:0,lastPlay:null,dailyCount:0,dailyDate:null,badges:{},sound:true}; }
  AudioFX.enabled = meta.sound !== false;
}
function saveData(){ localStorage.setItem(STORAGE_DATA, JSON.stringify(QURAN_DATA)); }
function saveGame(){ localStorage.setItem(STORAGE_GAME, JSON.stringify(state)); }
function saveMeta(){ localStorage.setItem(STORAGE_META, JSON.stringify(meta)); }

function todayStr(){ return new Date().toISOString().slice(0,10); }
function updateStreak(){
  const t = todayStr();
  if(meta.lastPlay === t) return;
  const y = new Date(); y.setDate(y.getDate()-1);
  if(meta.lastPlay === y.toISOString().slice(0,10)) meta.streak = (meta.streak||0)+1;
  else meta.streak = 1;
  meta.lastPlay = t;
  saveMeta();
}
function addDaily(){
  const t = todayStr();
  if(meta.dailyDate !== t){ meta.dailyCount=0; meta.dailyDate=t; }
  meta.dailyCount = (meta.dailyCount||0)+1;
  if(meta.dailyCount === 5){ state.coins += 25; saveGame(); alert("🎯 இன்றைய இலக்கு! +25 coins"); }
  saveMeta();
  updateDailyUI();
}
function updateDailyUI(){
  const c = meta.dailyCount||0;
  document.getElementById('dailyLabel').textContent = c + ' / 5';
  document.getElementById('dailyFill').style.width = Math.min(100, c/5*100) + '%';
}
function updateHeader(){
  document.getElementById('coinCount').textContent = state.coins;
  try{
    document.querySelectorAll('.coin-spin').forEach(function(el){
      el.classList.add('fast');
      setTimeout(function(){ el.classList.remove('fast'); }, 900);
    });
    try{ if(typeof AudioFX!=='undefined'&&AudioFX.playCoin) AudioFX.playCoin(); }catch(e){}
  }catch(e){}
  document.getElementById('streakCount').textContent = meta.streak||0;
  (function(){var sb=document.getElementById('soundBtn');if(sb){var on=meta.sound!==false;sb.innerHTML='<img src="icons/sound.png" alt="" class="header-sound-icon" style="opacity:'+(on?'1':'0.35')+'">';sb.title=on?'சப்தம் ON':'சப்தம் OFF';}})();
}

function shuffle(a){ const x=a.slice(); for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]];} return x; }

function switchScreen(id){
  if(id !== 'screenGarden'){ /* keep quiz only on garden if needed */ }
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  const scr = document.getElementById(id);
  if(scr) scr.classList.add('active');
  if(id==='screenBadges') renderBadges();
  if(id==='screenDhikr') initDhikr();
  if(id==='screenDua') initDua();
  if(id==='screenNabiDua') initNabiDua();
  if(id==='screenFinder') initFinder();
  if(id==='screenJuzPlayer'){ /* juz audio menu removed */ }
  if(id==='screenProfile'){
    try{ renderThemeGrid(); }catch(e){}
  }
  if(id==='screenFont'){
    try{ if(typeof updateScriptUI==='function') updateScriptUI(); }catch(e){}
  }
  if(id==='screenJuz'){
    try{ if(typeof initJuzFilterUI==='function') initJuzFilterUI(); }catch(e){}
  }
  if(id==='screenPrayer'){
    try{ if(typeof initPrayerTimes==='function') initPrayerTimes(); }catch(e){}
  }
}

function surahIdForNum(n){
  if(n===1){
    if(QURAN_DATA.fatiha) return 'fatiha';
  }
  const key = 's'+n;
  if(QURAN_DATA[key]) return key;
  // find by surahNum
  for(const id of Object.keys(QURAN_DATA)){
    if(QURAN_DATA[id].surahNum===n) return id;
  }
  return key;
}


