  4:  { name: "Lan Tana Lu",        start: {s:3,a:93},  end: {s:4,a:23},   surahs: [3,4] },
  5:  { name: "Wa'l-Muhsanat",      start: {s:4,a:24},  end: {s:4,a:147},  surahs: [4] },
  6:  { name: "La Yuhibbu-llah",    start: {s:4,a:148}, end: {s:5,a:81},   surahs: [4,5] },
  7:  { name: "Wa Iza Sami'u",      start: {s:5,a:82},  end: {s:6,a:110},  surahs: [5,6] },
  8:  { name: "Wa Lau Annana",      start: {s:6,a:111}, end: {s:7,a:87},   surahs: [6,7] },
  9:  { name: "Qal al-Mala'u",      start: {s:7,a:88},  end: {s:8,a:40},   surahs: [7,8] },
  10: { name: "Wa'lamu",            start: {s:8,a:41},  end: {s:9,a:92},   surahs: [8,9] },
  11: { name: "Ya'tadhiruna",       start: {s:9,a:93},  end: {s:11,a:5},   surahs: [9,10,11] },
  12: { name: "Wa Ma Min Dabbah",   start: {s:11,a:6},  end: {s:12,a:52},  surahs: [11,12] },
  13: { name: "Wa Ma Ubri'u",       start: {s:12,a:53}, end: {s:14,a:52},  surahs: [12,13,14] },
