  18: { name: "Qad Aflaha",         start: {s:23,a:1},  end: {s:25,a:20},  surahs: [23,24,25] },
  19: { name: "Wa Qal alladhina",   start: {s:25,a:21}, end: {s:27,a:55},  surahs: [25,26,27] },
  20: { name: "A'man Khalaq",       start: {s:27,a:56}, end: {s:29,a:45},  surahs: [27,28,29] },
  21: { name: "Utlu Ma Uhiya",      start: {s:29,a:46}, end: {s:33,a:30},  surahs: [29,30,31,32,33] },
  22: { name: "Wa Man Yaqnut",      start: {s:33,a:31}, end: {s:36,a:27},  surahs: [33,34,35,36] },
  23: { name: "Wa Mali",            start: {s:36,a:28}, end: {s:39,a:31},  surahs: [36,37,38,39] },
  24: { name: "Faman Azlamu",       start: {s:39,a:32}, end: {s:41,a:46},  surahs: [39,40,41] },
  25: { name: "Ilaihi Yuraddu",     start: {s:41,a:47}, end: {s:45,a:37},  surahs: [41,42,43,44,45] },
  26: { name: "Ha' Meem",           start: {s:46,a:1},  end: {s:50,a:45},  surahs: [46,47,48,49,50] },
  27: { name: "Qala Fama Khatbukum",start: {s:51,a:1},  end: {s:57,a:29},  surahs: [51,52,53,54,55,56,57] },
