// Derived maps (old JUZ_FIRST / bare arrays removed)
const JUZ_SURAHS = {};
const JUZ_FIRST_SURAH = [];
for (let __j = 1; __j <= 30; __j++) {
  JUZ_SURAHS[__j] = (JUZ_META[__j].surahs || []).slice();
  JUZ_FIRST_SURAH[__j - 1] = JUZ_SURAHS[__j][0];
}

function juzName(j){
  const m = JUZ_META[j];
  return m ? m.name : ('Juz ' + j);
}
function surahEn(n){
  const m = (typeof SURAH_META !== 'undefined') ? SURAH_META.find(function(x){ return x.n === n; }) : null;
  return m ? m.en : ('Surah ' + n);
}
/** Ayah-based range text: "Al-Baqarah 2:142 → Al-Baqarah 2:252" */
function juzRange(j){
  const m = JUZ_META[j];
  if(!m || !m.start || !m.end) return '';
  return surahEn(m.start.s) + ' ' + m.start.s + ':' + m.start.a +
    '  →  ' + surahEn(m.end.s) + ' ' + m.end.s + ':' + m.end.a;
}
function juzStartLabel(j){
  const m = JUZ_META[j];
  if(!m || !m.start) return '';
  return surahEn(m.start.s) + ' · ஆயத்து ' + m.start.a;
}
function juzEndLabel(j){
  const m = JUZ_META[j];
  if(!m || !m.end) return '';
  return surahEn(m.end.s) + ' · ஆயத்து ' + m.end.a;
}

function getSurahNumsForJuz(j){
  if(!j || j < 1 || j > 30) return null;
  const list = JUZ_SURAHS[j];
  return list ? list.slice() : null;
}

/** Primary juz for a surah (first juz that contains it) */
function primaryJuzForSurah(surahNum){
  const n = parseInt(surahNum, 10) || 0;
  for(let j = 1; j <= 30; j++){
    const list = JUZ_SURAHS[j] || [];
    if(list.indexOf(n) >= 0) return j;
  }
  return 0;
}

function allJuzForSurah(surahNum){
  const n = parseInt(surahNum, 10) || 0;
  const out = [];
  for(let j = 1; j <= 30; j++){
    if((JUZ_SURAHS[j]||[]).indexOf(n) >= 0) out.push(j);
  }
  return out;
}

function loadJuzFilter(){
  try {
    const v = parseInt(localStorage.getItem(JUZ_FILTER_KEY) || '0', 10);
    selectedJuz = (v >= 0 && v <= 30) ? v : 0;
  } catch(e){ selectedJuz = 0; }
}

function saveJuzFilter(){
  try { localStorage.setItem(JUZ_FILTER_KEY, String(selectedJuz)); } catch(e){}
}

function juzFilterLabelText(){
  if(!selectedJuz) return 'எல்லா ஜுஸ்வு · 114 சூரா';
  const nm = juzName(selectedJuz);
  const rg = juzRange(selectedJuz);
  const nums = getSurahNumsForJuz(selectedJuz) || [];
  return 'ஜுஸ்வு ' + selectedJuz + ' · ' + nm + (rg ? ' · ' + rg : '') + ' · ' + nums.length + ' சூரா';
}

function setJuzFilter(j){
  selectedJuz = j;
  saveJuzFilter();
  document.querySelectorAll('.juz-chip, .juz-pill').forEach(function(c){
    const v = parseInt(c.getAttribute('data-juz') || '0', 10);
    c.classList.toggle('active', v === selectedJuz);
  });
  const lab = document.getElementById('juzFilterLabel');
  if(lab) lab.textContent = juzFilterLabelText();
  if(typeof renderPlotsGrid === 'function') renderPlotsGrid();
  if(typeof renderJuzSettingsList === 'function') {
    try { renderJuzSettingsList(); } catch(e){}
  }
}

function buildJuzChips(container, compact){
  if(!container) return;
  container.innerHTML = '';
  if(compact){
    container.classList.add('home-juz-scroll');
    container.style.overflowX = 'auto';
    container.style.webkitOverflowScrolling = 'touch';
    container.style.touchAction = 'pan-x';
    const wrap = document.createElement('div');
    wrap.className = 'juz-pill-track';
    const all = document.createElement('button');
    all.type = 'button';
    all.className = 'juz-pill juz-pill-all' + (selectedJuz === 0 ? ' active' : '');
    all.setAttribute('data-juz', '0');
    all.textContent = 'எல்லாம்';
    all.onclick = function(){ setJuzFilter(0); };
    wrap.appendChild(all);
    for(let j = 1; j <= 30; j++){
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'juz-pill' + (selectedJuz === j ? ' active' : '');
      b.setAttribute('data-juz', String(j));
      b.textContent = String(j);
      if(j === 30) b.title = 'Juz Amma';
      b.onclick = function(){ setJuzFilter(j); };
      wrap.appendChild(b);
    }
    container.appendChild(wrap);
    return;
  }
  const all = document.createElement('button');
  all.type = 'button';
  all.className = 'juz-chip juz-chip-all' + (selectedJuz === 0 ? ' active' : '');
  all.setAttribute('data-juz', '0');
  all.textContent = 'எல்லா ஜுஸ்வு';
  all.onclick = function(){ setJuzFilter(0); };
  container.appendChild(all);
  for(let j = 1; j <= 30; j++){
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'juz-chip' + (selectedJuz === j ? ' active' : '');
    b.setAttribute('data-juz', String(j));
    b.textContent = 'ஜுஸ் ' + j;
    if(j === 30) b.title = 'Juz Amma';
    b.onclick = function(){ setJuzFilter(j); };
    container.appendChild(b);
  }
}

function renderJuzSettingsList(){
  const host = document.getElementById('juzSettingsList');
  if(!host) return;
  let h = '<p class="juz-explain">' +
    '<b>சூரா</b> → பெயரால் அத்தியாயம் (114).<br>' +
    '<b>ஜுஸ்</b> → <u>ஆயத்து எண்ணால்</u> தொடங்கும் 30 பாகங்கள்.<br>' +
    'எ.கா. ஜுஸ் 2 சூரா தொடக்கமல்ல — <b>பகரா ஆயத்து 142</b> முதல்.' +
    '</p>';
  h += '<div class="juz-icon-grid">';
  for(let j = 1; j <= 30; j++){
    const iconHtml = (j <= 20)
      ? '<img class="juz-big-icon" src="icons/juz-'+j+'.png" alt="Juz '+j+'" loading="lazy">'
      : '<span class="juz-big-fallback">'+j+'</span>';
    h += '<button type="button" class="juz-icon-btn" data-juz="'+j+'" title="ஜுஸ்வு '+j+' · '+juzName(j)+'">' +
      iconHtml +
      '</button>';
  }
  h += '</div>';
  host.innerHTML = h;
  host.querySelectorAll('.juz-icon-btn').forEach(function(btn){
    btn.onclick = function(){
      const jn = parseInt(btn.getAttribute('data-juz'),10);
      // Tap juz → start from that Juz's first AYAH
      openJuzReading(jn);
    };
  });
}

/** Juz detail — defined by START AYAH → END AYAH */
function openJuzDetail(j){
  const host = document.getElementById('juzSettingsList');
  if(!host) return;
  const m = JUZ_META[j];
  if(!m) return;
  let h = '<button type="button" class="back-btn" id="juzDetailBack">⬅ 30 ஜுஸ் பட்டியல்</button>';
  h += '<div class="juz-detail-card">';
  h += '<div class="jd-title">ஜுஸ்வு '+j+'</div>';
  h += '<div class="jd-name">'+juzName(j)+'</div>';
  h += '<div class="jd-ayah-box">';
  h += '<div class="jd-ayah-row"><span>▶️ தொடக்கம் (ஆயத்து)</span><strong>'+juzStartLabel(j)+'</strong></div>';
  h += '<div class="jd-ayah-row"><span>⏹️ முடிவு (ஆயத்து)</span><strong>'+juzEndLabel(j)+'</strong></div>';
  h += '</div>';
  h += '<button type="button" class="submit-btn" id="juzStartReadBtn" style="margin:10px 0;background:linear-gradient(135deg,#10b981,#059669)">▶️ இந்த ஆயத்திலிருந்து தொடங்கு</button>';
  h += '<p class="jd-note">ஜுஸ் <b>சூரா பெயரால் அல்ல</b> — <b>ஆயத்து எண்ணால்</b> பிரிக்கப்படும். '+
    'ஒரே சூரா (எ.கா. பகரா) பல ஜுஸ்களில் பரவும்.</p>';
  h += '<div class="jd-sub">இந்த ஆயத்து வரம்புக்குள் தொடர்புடைய சூராக்கள்</div>';
  h += '<div class="jd-surahs">';
  (m.surahs || []).forEach(function(n){
    const sm = SURAH_META.find(function(x){ return x.n === n; });
    const en = sm ? sm.en : ('Surah '+n);
    const ar = sm ? sm.ar : '';
    let tip = '';
    if(m.start.s === n && m.end.s === n) tip = 'ஆயத்து '+m.start.a+' – '+m.end.a;
    else if(m.start.s === n) tip = 'ஆயத்து '+m.start.a+' முதல் சூரா முடிவு வரை (இந்த ஜுஸில்)';
    else if(m.end.s === n) tip = 'சூரா தொடக்கம் முதல் ஆயத்து '+m.end.a+' வரை (இந்த ஜுஸில்)';
    else tip = 'முழு சூரா இந்த ஜுஸுக்குள்';
    h += '<button type="button" class="jd-surah-btn" data-n="'+n+'">' +
      '<span class="jd-n">சூரா '+n+'</span>' +
      '<span class="jd-ar" dir="rtl">'+ar+'</span>' +
      '<span class="jd-en">'+en+'</span>' +
      '<span class="jd-tip">'+tip+'</span></button>';
  });
  h += '</div></div>';
  host.innerHTML = h;
  const back = document.getElementById('juzDetailBack');
  if(back) back.onclick = function(){ renderJuzSettingsList(); };
  const startBtn = document.getElementById('juzStartReadBtn');
  if(startBtn) startBtn.onclick = function(){ openJuzReading(j); };
  host.querySelectorAll('.jd-surah-btn').forEach(function(b){
    b.onclick = function(){
      const n = parseInt(b.getAttribute('data-n'),10);
      if(typeof openGardenByNum === 'function') openGardenByNum(n);
    };
  });
}

function initJuzFilterUI(){
  loadJuzFilter();
  // Home page: NO juz number chips (user request)
  const homeBar = document.getElementById('homeJuzBar');
  if(homeBar){ homeBar.innerHTML = ''; homeBar.style.display = 'none'; }
  // Settings only: full juz list
  buildJuzChips(document.getElementById('juzFilterGrid'), false);
  const lab = document.getElementById('juzFilterLabel');
  if(lab) lab.textContent = juzFilterLabelText();
  renderJuzSettingsList();
  const allBtn = document.getElementById('juzFilterAllBtn');
  if(allBtn) allBtn.onclick = function(){ setJuzFilter(0); };
}




/* ===== Surah Level System: 12 levels × ~10 surahs, ranks, leaderboard ===== */
var SURAH_LEVEL_COUNT = 12; // 10 surahs each (last level has 4: 111-114)
var selectedSurahLevel = 1;

function getSurahLevelDef(level){
  // Level 1: 1-10, Level 2: 11-20, ... Level 11: 101-110, Level 12: 111-114
  var start = (level - 1) * 10 + 1;
  var end = Math.min(level * 10, 114);
  return { level: level, start: start, end: end, count: end - start + 1 };
}

function ensureLevelMeta(){
  if(!meta.levelProgress){
    meta.levelProgress = {
      unlocked: 1,
      selected: 1,
      ranks: {},
      completedAt: {},
      playerName: meta.playerName || 'வீரர்'
    };
  }
  if(!meta.leaderboard) meta.leaderboard = [];
  if(!meta.playerName) meta.playerName = meta.levelProgress.playerName || 'வீரர்';
  selectedSurahLevel = meta.levelProgress.selected || 1;
}

function isSurahDone(n){
  var id = surahIdForNum(n);
  var surah = QURAN_DATA[id];
  if(!surah || !surah.ayat || !surah.ayat.length) return false;
  var g = state.gardens[id] || {planted:[]};
  var P = g.planted.filter(Boolean).length;
  return P >= surah.ayat.length;
}

function surahStars(n){
  var id = surahIdForNum(n);
  var surah = QURAN_DATA[id];
  if(!surah || !surah.ayat || !surah.ayat.length) return 0;
  var g = state.gardens[id] || {planted:[]};
  var total = surah.ayat.length;
  var P = g.planted.filter(Boolean).length;
  if(P >= total && total > 0) return 3;
  if(P > 0) return Math.max(1, Math.round(P / total * 3));
  return 0;
}

function levelStats(level){
  var def = getSurahLevelDef(level);
  var done = 0, stars = 0;
  for(var n = def.start; n <= def.end; n++){
    if(isSurahDone(n)) done++;
    stars += surahStars(n);
  }
  var maxStars = def.count * 3;
  return { done: done, total: def.count, stars: stars, maxStars: maxStars, complete: done >= def.count };
}

function rankForLevel(st){
  if(!st.complete) return null;
  var pct = st.maxStars ? (st.stars / st.maxStars) : 0;
  if(pct >= 0.95) return 'diamond';
  if(pct >= 0.80) return 'platinum';
  if(pct >= 0.60) return 'gold';
  return 'silver';
}

var RANK_LABEL = {
  silver: '🥈 Silver',
  gold: '🥇 Gold',
  platinum: '💠 Platinum',
  diamond: '💎 Diamond'
};
var RANK_ORDER = { silver: 1, gold: 2, platinum: 3, diamond: 4 };

function isLevelUnlocked(level){
  ensureLevelMeta();
  if(level <= 1) return true;
  if(level <= (meta.levelProgress.unlocked || 1)) return true;
  // also unlock if previous is complete
  var prev = levelStats(level - 1);
  return prev.complete;
}

function checkLevelCompletions(){
  ensureLevelMeta();
  var changed = false;
  for(var lv = 1; lv <= SURAH_LEVEL_COUNT; lv++){
    var st = levelStats(lv);
    if(st.complete){
      if(!meta.levelProgress.ranks[lv]){
        var rank = rankForLevel(st);
        meta.levelProgress.ranks[lv] = rank;
        meta.levelProgress.completedAt[lv] = Date.now();
        // leaderboard entry
        meta.leaderboard.push({
          name: meta.playerName || 'வீரர்',
          level: lv,
          rank: rank,
          stars: st.stars,
          maxStars: st.maxStars,
          at: Date.now()
        });
        // keep last 100
        if(meta.leaderboard.length > 100) meta.leaderboard = meta.leaderboard.slice(-100);
        changed = true;
      }
      if(lv >= (meta.levelProgress.unlocked || 1) && lv < SURAH_LEVEL_COUNT){
        meta.levelProgress.unlocked = Math.max(meta.levelProgress.unlocked || 1, lv + 1);
        changed = true;
      }
    }
  }
  if(changed) saveMeta();
  return changed;
}

function setSurahLevel(lv){
  ensureLevelMeta();
  if(!isLevelUnlocked(lv)){
    alert('முதலில் Level ' + (lv - 1) + '-இல் உள்ள ' + getSurahLevelDef(lv-1).count + ' சூராக்களை முடிக்கவும்!');
    return;
  }
  selectedSurahLevel = lv;
  meta.levelProgress.selected = lv;
  saveMeta();
  renderPlotsGrid();
}

function renderLevelBar(){
  ensureLevelMeta();
  checkLevelCompletions();
  var bar = document.getElementById('surahLevelBar');
  if(!bar) return;
  var h = '';
  for(var lv = 1; lv <= SURAH_LEVEL_COUNT; lv++){
    var def = getSurahLevelDef(lv);
    var st = levelStats(lv);
    var unlocked = isLevelUnlocked(lv);
    var rank = meta.levelProgress.ranks[lv];
    var cls = 'slv-chip';
    if(!unlocked) cls += ' locked';
    else if(st.complete) cls += ' done';
    else if(lv === selectedSurahLevel) cls += ' active';
    var rankIcon = rank ? ({silver:'🥈',gold:'🥇',platinum:'💠',diamond:'💎'}[rank] || '') : '';
    h += '<button type="button" class="' + cls + '" data-slv="' + lv + '"' + (unlocked ? '' : ' disabled') + '>' +
      '<span class="slv-num">L' + lv + '</span>' +
      '<span class="slv-range">' + def.start + '-' + def.end + '</span>' +
      (rankIcon ? '<span class="slv-rank">' + rankIcon + '</span>' : '') +
      (unlocked && !st.complete ? '<span class="slv-prog">' + st.done + '/' + st.total + '</span>' : '') +
      (!unlocked ? '<span class="slv-lock">🔒</span>' : '') +
    '</button>';
  }
  bar.innerHTML = h;
  bar.querySelectorAll('[data-slv]').forEach(function(btn){
    btn.onclick = function(){ setSurahLevel(parseInt(btn.getAttribute('data-slv'), 10)); };
  });
}

function renderLevelLeaderboard(level){
  ensureLevelMeta();
  var box = document.getElementById('levelLeaderboard');
  if(!box) return;
  var entries = (meta.leaderboard || []).filter(function(e){ return e.level === level; });
  entries.sort(function(a,b){ return (a.at||0) - (b.at||0); });
  var h = '<div class="llb-title">🏆 Level ' + level + ' Leaderboard</div>';
  if(!entries.length){
    h += '<div class="llb-empty">இன்னும் யாரும் முடிக்கவில்லை — நீங்களே முதல் இடம் பிடிக்கலாம்!</div>';
  } else {
    h += '<div class="llb-list">';
    entries.slice(0, 10).forEach(function(e, i){
      var place = i + 1;
      var medal = place === 1 ? '🥇' : place === 2 ? '🥈' : place === 3 ? '🥉' : place + '.';
      h += '<div class="llb-row' + (place===1?' first':'') + '">' +
        '<span class="llb-place">' + medal + '</span>' +
        '<span class="llb-name">' + (e.name||'வீரர்') + '</span>' +
        '<span class="llb-rank">' + (RANK_LABEL[e.rank]||e.rank) + '</span>' +
        '<span class="llb-stars">⭐' + (e.stars||0) + '</span>' +
      '</div>';
    });
    h += '</div>';
  }
  box.innerHTML = h;
}


function renderPlotsGrid(){
  const grid = document.getElementById('plotsGrid');
  if(!grid) return;
  const _si = document.getElementById('surahSearchInput');
  const q = ((_si && _si.value)||'').trim().toLowerCase();
  // SURAH list only — Juz is a separate feature (not a surah filter)
  ensureLevelMeta();
  checkLevelCompletions();
  renderLevelBar();
  var def = getSurahLevelDef(selectedSurahLevel);
  let list = SURAH_META.filter(m=>{
    if(m.n < def.start || m.n > def.end) return false;
    if(!q) return true;
    return (m.en||'').toLowerCase().includes(q) || (m.ar||'').includes(q) || String(m.n).includes(q);
  });
  let currentId = null;
  for(const m of list){
    const id = surahIdForNum(m.n);
    const s = QURAN_DATA[id];
    if(!s || !s.ayat || !s.ayat.length){ if(!currentId) currentId = id; continue; }
    const g = state.gardens[id]||{planted:[]};
    const total = s.ayat.length;
    if(g.planted.filter(Boolean).length < total){ currentId = id; break; }
  }
  let totalStars=0, maxStars=list.length*3;
  var stLv = levelStats(selectedSurahLevel);
  var rankNow = meta.levelProgress.ranks[selectedSurahLevel];
  var unlockTxt = isLevelUnlocked(selectedSurahLevel) ? (stLv.complete ? ('✅ முடிந்தது ' + (RANK_LABEL[rankNow]||'')) : (stLv.done + '/' + stLv.total + ' சூரா')) : '🔒 பூட்டப்பட்டது';
  let h = '<div class="level-map-title"><img src="icons/tree-64.png" class="title-tree" alt=""> Level ' + selectedSurahLevel + ' · சூரா ' + def.start + '–' + def.end + ' <span class="slv-status">' + unlockTxt + '</span></div><div class="level-grid">';
  list.forEach(m=>{
    const id = surahIdForNum(m.n);
    const surah = QURAN_DATA[id];
    const hasData = !!(surah && surah.ayat && surah.ayat.length);
    const g = state.gardens[id]||{planted:[]};
    const total = hasData ? surah.ayat.length : (m.a||0);
    const P = hasData ? g.planted.filter(Boolean).length : 0;
    const done = hasData && total>0 && P>=total;
    const started = P>0;
    const isCurrent = id===currentId;
    let stars = done ? 3 : (P>0 ? Math.max(1, Math.round(P/total*3)) : 0);
    totalStars += stars;
    let cls = 'level-tile';
    if(done) cls += ' done';
    else if(isCurrent) cls += ' current';
    else if(started) cls += ' progress';
    else if(!hasData) cls += ' locked';
    else cls += ' locked';
    const num = m.n;
    const enName = String(m.en || ('Surah ' + num));
    let arName = String(m.ar || '');
    if(arName.indexOf('سُورَةُ') === 0) arName = arName.slice(6).trim();
    else if(arName.indexOf('سورة') === 0) arName = arName.slice(4).trim();
    let starsHtml = '';
    for(let s=1;s<=3;s++) starsHtml += s<=stars ? '⭐' : '☆';
    const badge = (isCurrent && !started) ? '<span class="level-new-badge">NEW!</span>' : '';
    const ayahLabel = m.a ? (m.a + ' ஆயத்து') : '';
    const inner =
      '<span class="level-num-badge">'+num+'</span>'+
      '<img src="icons/surah-72.png" alt="" class="level-surah-icon">';
    h += '<div class="'+cls+'" onclick="openGardenByNum('+m.n+')">'+badge+inner+
      '<div class="level-stars">'+starsHtml+'</div>'+
      '<div class="level-name-ar" dir="rtl">'+arName+'</div>'+
      '<div class="level-name">'+enName+'</div>'+
      (ayahLabel ? '<div class="level-ayahs">'+ayahLabel+'</div>' : '')+
      '</div>';
  });
  h += '</div><div class="level-progress-bar">⭐ '+totalStars+'/'+maxStars+'</div>';
  grid.innerHTML = h;
  updateHeader();
}

function stripBismillah(text, surahNum){
  if(!text) return '';
  var t = String(text).replace(/^\uFEFF/,'').trim();
  if(surahNum === 1 || surahNum === 9) return t;
  // Multiple Bismillah orthographies (Uthmani + IndoPak)
  t = t.replace(/^بِّ?سۡ?مِ[\s\u00A0]*ٱ?للَّ?هِ[\s\u00A0]*ٱ?لرَّحۡ?مَ[ـ\u0650]*ٰ?نِ[\s\u00A0]*ٱ?لرَّحِ[يىی]مِ[\s\u00A0]*/u, '');
  t = t.replace(/^بِسْمِ[\s\u00A0]+اللَّهِ[\s\u00A0]+الرَّحْمَٰنِ[\s\u00A0]+الرَّحِيمِ[\s\u00A0]*/u, '');
  t = t.replace(/^بسم الله الرحمن الرحيم[\s\u00A0]*/u, '');
  return t.trim();
}

async function ensureSurahLoaded(n){
  const id = surahIdForNum(n);
  if(QURAN_DATA[id] && QURAN_DATA[id].ayat && QURAN_DATA[id].ayat.length) return id;
  const meta = SURAH_META.find(m=>m.n===n);
  const endpoint = currentScript === 'uthmani'
    ? 'https://api.quran.com/api/v4/quran/verses/uthmani?chapter_number='+n
    : 'https://api.quran.com/api/v4/quran/verses/indopak?chapter_number='+n;
  const field = currentScript === 'uthmani' ? 'text_uthmani' : 'text_indopak';
  try {
    const [arRes, taRes] = await Promise.all([
      fetch(endpoint),
      fetch('https://api.alquran.cloud/v1/surah/'+n+'/ar.muyassar').catch(function(){return null}).then(function(){return {json:function(){return Promise.resolve({code:200,data:{ayahs:[]}})}}})
    ]);
    if(!arRes.ok) throw new Error('fail');
    const arData = await arRes.json();
    const verses = arData.verses || [];
    if(!verses.length) throw new Error('empty');
    let taList = [];
    if(taRes.ok){
      const taData = await taRes.json();
      taList = (taData.data && taData.data.ayahs || []).map(a=>a.text);
    }
    const ayat = verses.map((v,i)=>({
      ar: String(v[field]||'').replace(/^\uFEFF/,'').trim(),
      ta: taList[i]||''
    }));
    const newId = (n===1 && !QURAN_DATA.fatiha) ? 'fatiha' : 's'+n;
    QURAN_DATA[newId] = {
      nameAr: (meta&&meta.ar) || '',
      nameTa: n+'. '+((meta&&meta.en)||''),
      surahNum: n,
      ayat
    };
    if(!state.gardens[newId] || state.gardens[newId].planted.length !== ayat.length){
      state.gardens[newId] = {planted: Array(ayat.length).fill(false)};
    }
    saveData(); saveGame();
    return newId;
  } catch(e){
    alert('சூரா ஏற்ற முடியவில்லை. Internet தேவை.');
    return null;
  }
}


/** Build full Juz ayah queue: start ayah → end ayah (all surahs in between) */
async function buildJuzAyahQueue(j){
  const m = JUZ_META[j];
  if(!m || !m.start || !m.end) return [];
  const queue = [];
  const surahNums = [];
  // consecutive surah numbers from start.s to end.s
  for(let sn = m.start.s; sn <= m.end.s; sn++) surahNums.push(sn);
  for(let si = 0; si < surahNums.length; si++){
    const sn = surahNums[si];
    const id = await ensureSurahLoaded(sn);
    if(!id || !QURAN_DATA[id] || !QURAN_DATA[id].ayat) continue;
    const s = QURAN_DATA[id];
    const ayat = s.ayat;
    let from = 1;
    let to = ayat.length;
    if(sn === m.start.s) from = m.start.a;
    if(sn === m.end.s) to = m.end.a;
    from = Math.max(1, from);
    to = Math.min(ayat.length, to);
    for(let a = from; a <= to; a++){
      const ay = ayat[a - 1];
      if(!ay) continue;
      queue.push({
        id: id,
        surahNum: s.surahNum || sn,
        ayahNum: a,
        nameTa: s.nameTa || s.nameEn || ('சூரா '+sn),
        nameAr: s.nameAr || '',
        ar: ay.ar || '',
        ta: ay.ta || ''
      });
    }
  }
  return queue;
}

