/* ===== Themes (10) — white mixed in every palette ===== */
const THEMES = [
  {id:'midnight', name:'Midnight', base:'#060a1a', mode:'dark'},
  {id:'royal', name:'Royal Gold', base:'#1a1028', mode:'dark'},
  {id:'snow', name:'Snow White', base:'#f8fafc', mode:'light'},
  {id:'pearl', name:'Pearl Rose', base:'#fff5f7', mode:'light'},
  {id:'lavender', name:'Lavender', base:'#f5f3ff', mode:'light'},
  {id:'mint', name:'Mint Cream', base:'#f0fdf4', mode:'light'},
  {id:'ocean', name:'Ocean', base:'#0c1929', mode:'dark'},
  {id:'sunset', name:'Sunset', base:'#1c1018', mode:'dark'},
  {id:'emerald', name:'Emerald', base:'#0a1f18', mode:'dark'},
  {id:'amber', name:'Amber', base:'#1a1408', mode:'dark'},
];
const THEME_KEY = 'quran_theme_v1';

function applyTheme(id){
  const t = THEMES.find(x => x.id === id) || THEMES[0];
  const allIds = THEMES.map(x => x.id).concat(['rosewhite','peach','minty','sky','lemon','blush','cream']);
  allIds.forEach(function(th){ document.body.classList.remove('theme-'+th); });
  document.body.classList.add('theme-' + t.id);
  try{ localStorage.setItem(THEME_KEY, t.id); }catch(e){}
  const label = document.getElementById('themeLabel');
  if(label){
    const crowns = {royal:'👑 ', snow:'❄️ ', pearl:'🌸 ', mint:'🌿 ', ocean:'🌊 ', sunset:'🌅 ', emerald:'💚 ', amber:'✨ '};
    label.textContent = (crowns[t.id]||'') + t.name + (t.mode==='light' ? ' · Light' : ' · Dark');
  }
  document.querySelectorAll('.theme-swatch, .theme-dot').forEach(el=>{
    el.classList.toggle('active', el.dataset.theme === t.id);
  });
  const meta = document.querySelector('meta[name="theme-color"]');
  if(meta) meta.setAttribute('content', t.base || '#060a1a');
}

function renderThemeGrid(){
  const grid = document.getElementById('themeGrid');
  if(!grid) return;
  grid.innerHTML = '';
  grid.className = 'theme-grid';
  let saved = 'midnight';
  try{ saved = localStorage.getItem(THEME_KEY) || 'midnight'; }catch(e){}
  if(!THEMES.find(x => x.id === saved)) saved = 'midnight';
  THEMES.forEach(function(t){
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'theme-swatch' + (t.id === saved ? ' active' : '');
    btn.dataset.theme = t.id;
    btn.title = t.name;
    btn.innerHTML = '<span class="theme-swatch-label">' + t.name + '</span>';
    btn.onclick = function(){ applyTheme(t.id); };
    grid.appendChild(btn);
  });
  applyTheme(saved);
}







