/* ===== Touch helpers ===== */
function initTouchOptimizations(){
  // Prevent double-tap zoom on interactive elements (iOS)
  let lastTouchEnd = 0;
  document.addEventListener('touchend', function(e){
    const now = Date.now();
    if(now - lastTouchEnd <= 300){
      const t = e.target;
      if(t && (t.closest('button') || t.closest('.level-tile') || t.closest('.memory-card') ||
               t.closest('.game-card') || t.closest('.opt-btn') || t.closest('.ayah-dot'))){
        e.preventDefault();
      }
    }
    lastTouchEnd = now;
  }, {passive: false});

  // Visual pressed state via class for devices without :active reliability
  document.addEventListener('touchstart', function(e){
    const t = e.target.closest('button, .level-tile, .memory-card, .game-card, .opt-btn, .mode-btn, .ayah-dot');
    if(t) t.classList.add('is-pressed');
  }, {passive: true});
  document.addEventListener('touchend', function(e){
    document.querySelectorAll('.is-pressed').forEach(function(el){ el.classList.remove('is-pressed'); });
  }, {passive: true});
  document.addEventListener('touchcancel', function(){
    document.querySelectorAll('.is-pressed').forEach(function(el){ el.classList.remove('is-pressed'); });
  }, {passive: true});
}

