/* ===== Script: Indo-Pak / Uthmani ===== */
const SCRIPT_KEY = 'quran_script_v1';
let currentScript = 'indopak';

function applyScriptFonts(){
  document.body.classList.remove('script-uthmani','script-indopak');
  if(currentScript === 'uthmani'){
    document.body.classList.add('script-uthmani');
    document.documentElement.style.setProperty('--font-ar', "'UthmanicHafs','Amiri Quran','Scheherazade New','Noto Naskh Arabic','AlMajeed',serif");
  } else {
    document.body.classList.add('script-indopak');
    document.documentElement.style.setProperty('--font-ar', "'AlMajeed','MuhammadiQuranic','UthmanicHafs','Amiri Quran','Scheherazade New','Noto Naskh Arabic',serif");
  }
}

function getDefaultForScript(script){
  return script === 'uthmani' ? DEFAULT_QURAN_UTHMANI : DEFAULT_QURAN_INDOPAK;
}

function applyScript(script, forceReload){
  const s = (script === 'uthmani') ? 'uthmani' : 'indopak';
  if(s === currentScript && !forceReload) {
    // just update UI
  } else {
    currentScript = s;
    try{ localStorage.setItem(SCRIPT_KEY, s); }catch(e){}
    // Replace local surah texts from embedded defaults; keep garden progress
    const src = getDefaultForScript(s);
    Object.keys(src).forEach(id=>{
      const keepGarden = state.gardens[id];
      QURAN_DATA[id] = structuredClone(src[id]);
      if(keepGarden && keepGarden.planted && keepGarden.planted.length === QURAN_DATA[id].ayat.length){
        state.gardens[id] = keepGarden;
      } else {
        state.gardens[id] = {planted: Array(QURAN_DATA[id].ayat.length).fill(false)};
      }
    });
    // Clear non-local surahs so they re-fetch with new script
    Object.keys(QURAN_DATA).forEach(id=>{
      if(!src[id]) delete QURAN_DATA[id];
    });
    JUZ_CACHE = {};
    saveData(); saveGame();
    applyScriptFonts();
  }
  const label = document.getElementById('scriptLabel');
  if(label) label.textContent = s === 'uthmani' ? 'Uthmani (மதீனா)' : 'Indo-Pak (தெற்காசிய)';
  document.querySelectorAll('.script-btn').forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.script === currentScript);
  });
}

function initScriptSelector(){
  let saved = 'indopak';
  try{ saved = localStorage.getItem(SCRIPT_KEY) || 'indopak'; }catch(e){}
  currentScript = saved;
  applyScriptFonts();
  document.querySelectorAll('.script-btn').forEach(btn=>{
    btn.onclick = function(){
      if(btn.dataset.script === currentScript) return;
      applyScript(btn.dataset.script, true);
      // refresh current view if open
      if(currentSurah && QURAN_DATA[currentSurah]){
        try{ openGarden(currentSurah); }catch(e){}
      }
    };
  });
  applyScript(saved, false);
  // If saved was uthmani, need to actually load uthmani data
  if(saved === 'uthmani') applyScript('uthmani', true);
}


