const PRAYER_PLACES = {"தமிழ்நாடு":[{name:"சென்னை",lat:13.0827,lng:80.2707}]};

/* ===== Prayer times (தொழுகை நேரம்) ===== */
const PRAYER_KEY = 'quran_prayer_loc_v1';
const PRAYER_NAMES = [
  { key: 'Fajr', ta: 'ஃபஜ்ர்' },
  { key: 'Dhuhr', ta: 'ளுஹர்' },
  { key: 'Asr', ta: 'அஸர்' },
  { key: 'Maghrib', ta: 'மக்ரிப்' },
  { key: 'Isha', ta: 'இஷா' }
];

function prayerPad(n){ return String(n).padStart(2,'0'); }

function prayerToMinutes(hhmm){
  if(!hhmm) return null;
  const p = String(hhmm).trim().split(':');
  if(p.length < 2) return null;
  return parseInt(p[0],10)*60 + parseInt(p[1],10);
}

function prayerFormat12(hhmm){
  if(!hhmm) return '—';
  const parts = String(hhmm).split(':');
  let h = parseInt(parts[0],10), m = parseInt(parts[1],10);
  if(isNaN(h)||isNaN(m)) return hhmm;
  const am = h < 12;
  const h12 = h % 12 || 12;
  return h12 + ':' + prayerPad(m) + (am ? ' AM' : ' PM');
}

function loadPrayerLoc(){
  try { return JSON.parse(localStorage.getItem(PRAYER_KEY) || 'null'); } catch(e){ return null; }
}
function savePrayerLoc(loc){
  try { localStorage.setItem(PRAYER_KEY, JSON.stringify(loc)); } catch(e){}
}

function renderPrayerTimes(timings, metaText){
  const list = document.getElementById('prayerList');
  const meta = document.getElementById('prayerMeta');
  const nextEl = document.getElementById('prayerNext');
  if(meta) meta.textContent = metaText || '';
  if(!list || !timings) return;

  const now = new Date();
  const nowMin = now.getHours()*60 + now.getMinutes();
  let nextName = null, nextTime = null;

  list.innerHTML = '';
  PRAYER_NAMES.forEach(function(p){
    const t = timings[p.key];
    const mins = prayerToMinutes(t);
    const row = document.createElement('div');
    row.className = 'prayer-row';
    if(mins != null && mins <= nowMin) row.classList.add('passed');
    if(mins != null && mins > nowMin && !nextName){
      nextName = p.ta;
      nextTime = t;
      row.classList.add('next');
    }
    row.innerHTML = '<span>'+p.ta+'</span><strong>'+prayerFormat12(t)+'</strong>';
    list.appendChild(row);
  });

  if(nextEl){
    if(nextName) nextEl.textContent = 'அடுத்து: ' + nextName + ' · ' + prayerFormat12(nextTime);
    else nextEl.textContent = 'இன்றைய தொழுகைகள் முடிந்தது';
  }
}

async function fetchPrayerTimes(lat, lng, cityLabel){
  const meta = document.getElementById('prayerMeta');
  if(meta) meta.textContent = 'நேரம் ஏற்றுகிறது…';
  // method=1 Muslim World League — good default for many regions
  const url = 'https://api.aladhan.com/v1/timings?latitude='+encodeURIComponent(lat)+
    '&longitude='+encodeURIComponent(lng)+'&method=1&school='+(localStorage.getItem('quran_prayer_madhab_v1')==='hanafi'?1:0);
  try{
    const res = await fetch(url);
    if(!res.ok) throw new Error('network');
    const data = await res.json();
    const timings = data && data.data && data.data.timings;
    if(!timings) throw new Error('empty');
    const date = (data.data.date && data.data.date.readable) || '';
    const label = (cityLabel || (lat.toFixed(2)+', '+lng.toFixed(2))) + (date ? ' · ' + date : '');
    renderPrayerTimes(timings, label);
    return timings;
  } catch(e){
    if(meta) meta.textContent = 'நேரம் கிடைக்கவில்லை (இணையம் தேவை)';
    console.warn('prayer times', e);
    return null;
  }
}

function initPrayerTimes(){
  // Place selects
  try {
    const st = document.getElementById('prayerStateSelect');
    const ct = document.getElementById('prayerCitySelect');
    if(st && ct && typeof PRAYER_PLACES === 'object'){
      const states = Object.keys(PRAYER_PLACES);
      st.innerHTML = '';
      states.forEach(function(s){ const o=document.createElement('option'); o.value=s; o.textContent=s; st.appendChild(o); });
      if(states.indexOf('தமிழ்நாடு')>=0) st.value='தமிழ்நாடு';
      function fillCities(){
        const list = PRAYER_PLACES[st.value]||[];
        ct.innerHTML='';
        list.forEach(function(c,i){ const o=document.createElement('option'); o.value=String(i); o.textContent=c.name; ct.appendChild(o); });
        if(st.value==='தமிழ்நாடு'){ const ix=list.findIndex(function(c){return c.name==='சென்னை';}); if(ix>=0) ct.value=String(ix); }
      }
      st.onchange = fillCities; fillCities();
      const go = document.getElementById('prayerCityGoBtn');
      if(go) go.onclick = function(){
        const list = PRAYER_PLACES[st.value]||[];
        const p = list[parseInt(ct.value,10)||0];
        if(!p) return;
        const label = st.value + ' · ' + p.name;
        savePrayerLoc({lat:p.lat,lng:p.lng,label:label});
        fetchPrayerTimes(p.lat, p.lng, label);
      };
    }
    const sh = document.getElementById('madhabShafi');
    const ha = document.getElementById('madhabHanafi');
    function syncMadhab(){
      const m = localStorage.getItem('quran_prayer_madhab_v1')||'shafi';
      if(sh) sh.classList.toggle('active', m==='shafi');
      if(ha) ha.classList.toggle('active', m==='hanafi');
    }
    syncMadhab();
    if(sh) sh.onclick = function(){ localStorage.setItem('quran_prayer_madhab_v1','shafi'); syncMadhab(); const s=loadPrayerLoc(); if(s&&s.lat!=null) fetchPrayerTimes(s.lat,s.lng,s.label||''); };
    if(ha) ha.onclick = function(){ localStorage.setItem('quran_prayer_madhab_v1','hanafi'); syncMadhab(); const s=loadPrayerLoc(); if(s&&s.lat!=null) fetchPrayerTimes(s.lat,s.lng,s.label||''); };
  } catch(e){ console.warn(e); }
  const locateBtn = document.getElementById('prayerLocateBtn');
  const refreshBtn = document.getElementById('prayerRefreshBtn');
  if(!locateBtn && !refreshBtn) return;

  const saved = loadPrayerLoc();
  if(saved && saved.lat != null && saved.lng != null){
    fetchPrayerTimes(saved.lat, saved.lng, saved.label || '');
  }

  if(locateBtn){
    locateBtn.onclick = function(){
      const meta = document.getElementById('prayerMeta');
      if(!navigator.geolocation){
        if(meta) meta.textContent = 'இந்த சாதனத்தில் இடம் ஆதரவு இல்லை';
        return;
      }
      if(meta) meta.textContent = 'இடம் தேடுகிறது…';
      navigator.geolocation.getCurrentPosition(function(pos){
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const label = 'உங்கள் இடம்';
        savePrayerLoc({ lat: lat, lng: lng, label: label });
        fetchPrayerTimes(lat, lng, label);
      }, function(err){
        if(meta) meta.textContent = 'இடம் கிடைக்கவில்லை — அனுமதி கொடுங்கள்';
        console.warn(err);
      }, { enableHighAccuracy: false, timeout: 12000, maximumAge: 600000 });
    };
  }

  if(refreshBtn){
    refreshBtn.onclick = function(){
      const saved2 = loadPrayerLoc();
      if(saved2 && saved2.lat != null){
        fetchPrayerTimes(saved2.lat, saved2.lng, saved2.label || '');
      } else if(locateBtn){
        locateBtn.click();
      }
    };
  }
}


