/* ===== மீலாது நிகழ்வு · ஸலவாத் Leaderboard ===== */
function ensureMiladMeta(){
  if(!meta.milad){
    meta.milad = { total: 0, today: 0, todayDate: null };
  }
  var today = new Date().toISOString().slice(0,10);
  if(meta.milad.todayDate !== today){
    meta.milad.today = 0;
    meta.milad.todayDate = today;
  }
  if(!meta.miladBoard) meta.miladBoard = [];
}
function addMiladSalawat(n){
  if(n <= 0) return;
  ensureMiladMeta();
  meta.milad.total = (meta.milad.total || 0) + n;
  meta.milad.today = (meta.milad.today || 0) + n;
  var name = meta.playerName || 'வீரர்';
  var found = null;
  for(var i=0;i<meta.miladBoard.length;i++){
    if(meta.miladBoard[i].name === name){ found = meta.miladBoard[i]; break; }
  }
  if(found){
    found.total = meta.milad.total;
    found.today = meta.milad.today;
    found.at = Date.now();
  } else {
    meta.miladBoard.push({ name: name, total: meta.milad.total, today: meta.milad.today, at: Date.now() });
  }
  try{ localStorage.setItem('qg_salawat_count', String(meta.milad.total)); }catch(e){}
  saveMeta();
}
function renderMiladLeaderboard(){
  ensureMiladMeta();
  var filter = (window.__miladLbFilter || 'all');
  var board = (meta.miladBoard || []).slice();
  var now = Date.now();
  var dayMs = 86400000;
  if(filter === 'daily'){
    board = board.filter(function(e){ return (now - (e.at||0)) < dayMs; });
  } else if(filter === 'weekly'){
    board = board.filter(function(e){ return (now - (e.at||0)) < dayMs * 7; });
  }
  board.sort(function(a,b){
    if(filter === 'daily') return (b.today||0) - (a.today||0);
    return (b.total||0) - (a.total||0);
  });

  var podium = document.getElementById('miladLbPodium');
  var list = document.getElementById('miladLbList');
  var you = document.getElementById('miladLbYou');
  var rankIcons = {1:'icons/rank1.png', 2:'icons/rank2.png', 3:'icons/rank3.png'};

  if(podium){
    var slots = [
      { place: 2, e: board[1] },
      { place: 1, e: board[0] },
      { place: 3, e: board[2] }
    ];
    var ph = '';
    slots.forEach(function(s){
      var name = s.e ? (s.e.name || 'வீரர்') : '—';
      var score = s.e ? (filter==='daily' ? (s.e.today||0) : (s.e.total||0)) : '—';
      var firstCls = s.place === 1 ? ' podium-first' : '';
      ph += '<div class="podium-slot'+firstCls+'">'+
        '<img src="'+rankIcons[s.place]+'" alt="'+s.place+'" class="podium-rank-img">'+
        '<div class="podium-name">'+name+'</div>'+
        '<div class="podium-score">💚 '+score+'</div>'+
      '</div>';
    });
    podium.innerHTML = ph;
  }

  if(list){
    if(!board.length){
      list.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-dim)">🌙 மீலாது ஸலவாத் இன்னும் தொடங்கவில்லை<br><small>நபி மீது ஸலவாத் → ஓதி எண்ணுங்கள்!</small></div>';
    } else {
      var lh = '';
      board.forEach(function(e, i){
        var place = i + 1;
        var score = filter==='daily' ? (e.today||0) : (e.total||0);
        lh += '<div class="plb-row">'+
          '<span class="plb-pos">'+place+'</span>'+
          '<span class="plb-name">'+(e.name||'வீரர்')+'</span>'+
          '<span class="plb-pts">💚 '+score+'</span>'+
        '</div>';
      });
      list.innerHTML = lh;
    }
  }

  if(you){
    var myName = meta.playerName || 'வீரர்';
    var myPlace = '—';
    for(var i=0;i<board.length;i++){
      if(board[i].name === myName){ myPlace = i+1; break; }
    }
    var myScore = filter==='daily' ? (meta.milad.today||0) : (meta.milad.total||0);
    you.innerHTML =
      '<span class="plb-pos">#'+myPlace+'</span>'+
      '<div class="plb-you-avatar">'+(myName.charAt(0)||'வ')+'</div>'+
      '<div class="plb-you-info">'+
        '<div class="plb-you-name">'+myName+'</div>'+
        '<div class="plb-you-meta">இன்று '+(meta.milad.today||0)+' · மொத்தம் '+(meta.milad.total||0)+' ஸலவாத்</div>'+
      '</div>'+
      '<span class="plb-pts">💚 '+myScore+'</span>';
  }
}
function initMilad(){
  ensureMiladMeta();
  window.__miladLbFilter = window.__miladLbFilter || 'all';
  var filters = document.getElementById('miladLbFilters');
  if(filters){
    filters.querySelectorAll('.plb-filter').forEach(function(btn){
      btn.classList.toggle('active', btn.getAttribute('data-filter') === window.__miladLbFilter);
      btn.onclick = function(){
        window.__miladLbFilter = btn.getAttribute('data-filter');
        filters.querySelectorAll('.plb-filter').forEach(function(b){ b.classList.toggle('active', b===btn); });
        renderMiladLeaderboard();
      };
    });
  }
  renderMiladLeaderboard();
  var btn = document.getElementById('miladBackBtn');
  if(btn){
    btn.onclick = function(){
      if(typeof switchScreen === 'function') switchScreen('screenSelect');
    };
  }
}

function initSalawat(){
  ensureMiladMeta();
  var count = meta.milad.total || 0;
  try{
    var legacy = parseInt(localStorage.getItem('qg_salawat_count')||'0',10)||0;
    if(legacy > count){
      meta.milad.total = legacy;
      count = legacy;
      var name = meta.playerName || 'வீரர்';
      var found = null;
      for(var i=0;i<meta.miladBoard.length;i++){
        if(meta.miladBoard[i].name === name){ found = meta.miladBoard[i]; break; }
      }
      if(found){ found.total = legacy; found.at = Date.now(); }
      else { meta.miladBoard.push({name:name, total:legacy, today:meta.milad.today||0, at:Date.now()}); }
      saveMeta();
    }
  }catch(e){}

  var countEl = document.getElementById('salawatCount');
  var arEl = document.getElementById('salawatMainAr');
  var types = document.getElementById('salawatTypes');
  if(countEl) countEl.textContent = String(count);

  if(types && !types.dataset.ready){
    types.dataset.ready = '1';
    types.innerHTML = SALAWAT_TYPES.map(function(t, i){
      return '<button type="button" class="salawat-type-card'+(i===0?' active':'')+'" data-i="'+i+'">'+
        '<div class="salawat-type-num">'+t.n+'</div>'+
        '<div class="salawat-type-name">'+t.name+'</div>'+
        '<div class="salawat-type-ar">'+t.ar+'</div></button>';
    }).join('');
    types.onclick = function(ev){
      var card = ev.target.closest('.salawat-type-card');
      if(!card) return;
      var i = parseInt(card.getAttribute('data-i'),10);
      var t = SALAWAT_TYPES[i];
      if(!t) return;
      types.querySelectorAll('.salawat-type-card').forEach(function(c){ c.classList.remove('active'); });
      card.classList.add('active');
      if(arEl) arEl.textContent = t.ar;
      try{ if(typeof AudioFX!=='undefined'&&AudioFX.playClick) AudioFX.playClick(); }catch(e){}
    };
  }

  var tap = document.getElementById('salawatTapBtn');
  if(tap && !tap.dataset.bound){
    tap.dataset.bound = '1';
    tap.onclick = function(){
      addMiladSalawat(1);
      count = meta.milad.total;
      if(countEl) countEl.textContent = String(count);
      try{ if(typeof AudioFX!=='undefined'&&AudioFX.playTick) AudioFX.playTick(); else if(AudioFX&&AudioFX.playClick) AudioFX.playClick(); }catch(e){}
      tap.style.transform = 'scale(0.97)';
      setTimeout(function(){ tap.style.transform = ''; }, 120);
      var h = document.getElementById('miladSalawatHint');
      if(h) h.innerHTML = '🌙 மீலாது · இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b> · <button type="button" id="goMiladFromSalawat" style="background:rgba(255,213,79,.2);border:1px solid rgba(255,213,79,.5);color:#ffd54f;border-radius:8px;padding:2px 8px;font-size:11px;font-weight:800;cursor:pointer">லீடர்போர்டு</button>';
      var go = document.getElementById('goMiladFromSalawat');
      if(go) go.onclick = function(){ if(typeof switchScreen==='function') switchScreen('screenMilad'); };
    };
  }
  var reset = document.getElementById('salawatResetBtn');
  if(reset && !reset.dataset.bound){
    reset.dataset.bound = '1';
    reset.onclick = function(){
      if(!confirm('எண்ணிக்கையை மீட்டமைக்கவா? (மீலாது லீடர்போர்டும் ரீசெட் ஆகும்)')) return;
      ensureMiladMeta();
      meta.milad.total = 0;
      meta.milad.today = 0;
      var name = meta.playerName || 'வீரர்';
      meta.miladBoard = (meta.miladBoard||[]).filter(function(e){ return e.name !== name; });
      saveMeta();
      try{ localStorage.setItem('qg_salawat_count', '0'); }catch(e){}
      count = 0;
      if(countEl) countEl.textContent = '0';
    };
  }
  var back = document.getElementById('salawatBackBtn');
  if(back) back.onclick = function(){ if(typeof switchScreen==='function') switchScreen('screenSelect'); };

  var card = document.querySelector('.salawat-counter-card');
  if(card && !document.getElementById('miladSalawatHint')){
    var hint = document.createElement('div');
    hint.id = 'miladSalawatHint';
    hint.style.cssText = 'text-align:center;font-size:11px;color:#ffd54f;margin-top:8px;font-weight:700';
    hint.innerHTML = '🌙 மீலாது · இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b> · <button type="button" id="goMiladFromSalawat" style="background:rgba(255,213,79,.2);border:1px solid rgba(255,213,79,.5);color:#ffd54f;border-radius:8px;padding:2px 8px;font-size:11px;font-weight:800;cursor:pointer">லீடர்போர்டு</button>';
    card.appendChild(hint);
  } else {
    var h2 = document.getElementById('miladSalawatHint');
    if(h2) h2.innerHTML = '🌙 மீலாது · இன்று <b>'+(meta.milad.today||0)+'</b> · மொத்தம் <b>'+(meta.milad.total||0)+'</b> · <button type="button" id="goMiladFromSalawat" style="background:rgba(255,213,79,.2);border:1px solid rgba(255,213,79,.5);color:#ffd54f;border-radius:8px;padding:2px 8px;font-size:11px;font-weight:800;cursor:pointer">லீடர்போர்டு</button>';
  }
  var goBtn = document.getElementById('goMiladFromSalawat');
  if(goBtn) goBtn.onclick = function(){ if(typeof switchScreen==='function') switchScreen('screenMilad'); };
}

// hook switchScreen for Salawat + Milad
(function(){
  var tries = 0;
  function hook(){
    if(typeof switchScreen !== 'function'){
      if(tries++ < 20) setTimeout(hook, 100);
      return;
    }
    if(switchScreen.__salawatHooked) return;
    var orig = switchScreen;
    switchScreen = function(id){
      var r = orig.apply(this, arguments);
      if(id === 'screenSalawat') try{ initSalawat(); }catch(e){}
      if(id === 'screenMilad') try{ initMilad(); }catch(e){}
      return r;
    };
    switchScreen.__salawatHooked = true;
    if(orig.__sfxWrapped) switchScreen.__sfxWrapped = true;
    if(orig.__gameHistHooked) switchScreen.__gameHistHooked = true;
  }
  hook();
})();
